  const commonNav = {
    'index.html':'nav.home','analyze.html':'nav.analysis','pricing.html':'nav.pricing','about.html':'nav.about',
    'contact.html':'nav.contact','dashboard.html':'nav.dashboard','find-my-place.html':'nav.findMyPlace','location-battle.html':'nav.locationBattle'
  };
  function keyForHref(href) {
    const name=(href||'').split('/').pop().split('?')[0] || 'index.html';
    return commonNav[name] || null;
  }
  function setText(el,key,html=false) {
    if (!el || !key) return;
    const value=window.i18n.t(key);
    if (html) el.innerHTML=value; else el.textContent=value;
  }
  function setLeading(el,key) {
    if (!el) return;
    const v=window.i18n.t(key);
    let n=el.firstChild;
    if (!n || n.nodeType!==Node.TEXT_NODE) { n=document.createTextNode(''); el.insertBefore(n,el.firstChild); }
    n.textContent=v+' ';
  }
  function applyCommon() {
    document.querySelectorAll('.nav-drawer-item,.menu-link,.site-menu-body a,.nav-links a,.site-nav a,.drawer-links a').forEach(a=>{
      const k=keyForHref(a.getAttribute('href'));
      if(k) setLeading(a,k);
    });
    document.querySelectorAll('.footer-contact-info').forEach(el=>{
      const v=window.i18n.t('footer.location');
      if(el.querySelector('a')) {
        let n=el.firstChild;
        if(!n || n.nodeType!==Node.TEXT_NODE){ n=document.createTextNode(''); el.insertBefore(n,el.firstChild); }
        n.textContent=v+' ';
      } else setText(el,'footer.location');
    });
    document.querySelectorAll('.global-footer-bottom span:last-child').forEach(el=>setText(el,'footer.tagline'));
    document.querySelectorAll('[data-i18n-before]').forEach(el=>setLeading(el,el.dataset.i18nBefore));
    document.querySelectorAll('.nav-hamburger,.site-menu-btn').forEach(el=>el.setAttribute('aria-label',window.i18n.t('nav.menu')));
    document.querySelectorAll('.site-nav,.nav-links,.site-header nav').forEach(el=>el.setAttribute('aria-label',window.i18n.t('nav.menu')));
  }

